"""Give a live internal partition disjoint mesh keys and exact patch transport.

The raw provider keeps its original patch owner on every face, so partial
assembly can still select the complete valid patch. The shared region marker
is promoted to public multi-Bundle ownership after network assembly. Existing
vertex/face identities and mouth frames are restored explicitly after welding.
"""
import bpy
from . import curved_corner_nodes as c
from . import curved_internal_partition_nodes as partition

NAME = 'Prochitecture Streets / Owned internal plateau partition v1'
SURFACE_KIND = 7  # A shared separator region, with explicit multi-Bundle membership.
MARKER = '_ir_separator_face'
REGION = '_ir_region_id'
PATCH = '_ir_patch_owner'


def publish(g, geometry, material=None):
    """Promote region faces after assembly has retained the whole patch owner."""
    selection = c.named(g, MARKER, 'BOOLEAN'); region = c.named(g, REGION, 'INT')
    for name, new in (('st_cn_kind', SURFACE_KIND), ('st_cn_owner', region),
                      ('_cn_face_kind', SURFACE_KIND), ('_cn_face_owner', region),
                      ('st_cn_region_id', region)):
        geometry = g.store(geometry, name, c.choose(g, selection, new, c.named(g, name, 'INT'), 'INT'), 'FACE', 'INT')
    if material is not None:
        node = g.node('GeometryNodeSetMaterial', 'Shared separator region material')
        for key, value in (('Geometry', geometry), ('Selection', selection), ('Material', material)):
            g.bind(value, node.inputs[key])
        geometry = c.V(g, node.outputs['Geometry'])
    return geometry


def face_read(g, geometry, name, at, kind='INT'):
    node = g.node('GeometryNodeSampleIndex', 'Preserve exact original face '+name)
    node.data_type = kind; node.domain = 'FACE'; node.clamp = False
    for key, value in (('Geometry', geometry), ('Value', c.named(g, name, kind)), ('Index', at)):
        g.bind(value, node.inputs[key])
    return c.V(g, node.outputs['Value'])


def build():
    if NAME in bpy.data.node_groups: return bpy.data.node_groups[NAME]
    g = c.Graph(NAME)
    for key in ('Cycle', 'Pavement'): g.socket(key, 'NodeSocketGeometry')
    for key in ('Patch ID', 'Region ID'): g.socket(key, 'NodeSocketInt', default=0)
    for key, value in (('Join Radius', .5), ('Cell Size', .4), ('Chord Error', .005)):
        g.socket(key, 'NodeSocketFloat', default=value)
    for key in ('Geometry', 'Status'): g.socket(key, 'NodeSocketGeometry', 'OUTPUT')
    g.socket('Valid', 'NodeSocketBool', 'OUTPUT')
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    original = inp.outputs['Pavement']; patch = c.V(g, inp.outputs['Patch ID']); region = c.V(g, inp.outputs['Region ID'])
    index = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    valid = 1.
    for value in (patch, region):
        valid = valid*g.math('GREATER_THAN', value, -.5)*g.math('LESS_THAN', value, 2**20)
    key = g.separate(c.named(g, '_bridge_key', 'FLOAT_VECTOR'))
    collision = g.math('COMPARE', key[0], 5.)*g.math('COMPARE', key[1], region)
    valid = valid*c._stat(g, original, 1.-collision)
    valid = valid*c._stat(g, original, g.math('COMPARE', c.named(g, '_cn_face_kind', 'INT'), 0.)*
        g.math('COMPARE', c.named(g, '_cn_face_owner', 'INT'), patch)*
        c.named(g, '_cn_face_owned', 'BOOLEAN'), domain='FACE')
    identity_valid = valid
    call = g.node('GeometryNodeGroup', 'Existing rounded direct-quad partition with strict failure preservation')
    call.node_tree = partition.build()
    for name in ('Cycle', 'Pavement', 'Join Radius', 'Cell Size', 'Chord Error'):
        g.bind(inp.outputs[name], call.inputs[name])
    result = c.V(g, call.outputs['Geometry'])
    valid = valid*c.V(g, call.outputs['Valid'])*g.math('LESS_THAN', c._count(g, result), 2**20)
    old = c.named(g, '_ip_source_vertex', 'INT'); is_old = g.math('GREATER_THAN', old, -.5)
    # Seam duplicates carry the same source vertex but may have different
    # default metadata. Never allow Merge by Distance to average owner IDs,
    # mouth/rank addresses or local frames on the retained boundary.
    attributes = (
        ('st_cn_kind', 'INT', 0), ('st_cn_owner', 'INT', patch),
        ('st_cn_mouth', 'INT', -1), ('st_cn_rank', 'INT', -1),
        ('_cn_frame_position', 'FLOAT_VECTOR', g.position()),
        ('_cn_frame_origin', 'FLOAT_VECTOR', g.xyz(0., 0., 0.)),
        ('_cn_framed', 'BOOLEAN', False),
        ('_bridge_key', 'FLOAT_VECTOR', g.xyz(5., region, index)),
    )
    for name, kind, new in attributes:
        value = c.choose(g, is_old, c._read(g, original, name, old, kind), new,
                         'VECTOR' if kind == 'FLOAT_VECTOR' else kind)
        result = c._store(g, result, name, value, kind)
    old_face = c.named(g, '_ip_source_face', 'INT')
    kept = g.math('GREATER_THAN', old_face, -.5)
    grass = (1.-kept)*g.math('COMPARE', c.named(g, '_ic_surface', 'INT'), 1.)
    for name, kind, new in (('_cn_face_kind', 'INT', 0), ('_cn_face_owner', 'INT', patch),
                            ('_cn_face_owned', 'BOOLEAN', True), ('st_separator_closure', 'BOOLEAN', grass)):
        value = c.choose(g, kept, face_read(g, original, name, old_face, kind), new, kind)
        result = g.store(result, name, value, 'FACE', kind)
    for name, value, kind in ((MARKER, grass, 'BOOLEAN'), (REGION, region, 'INT'), (PATCH, patch, 'INT')):
        result = g.store(result, name, value, 'FACE', kind)
    result = c._store(g, result, '_ip_requires_namespace', False, 'BOOLEAN')
    status = c._store(g, call.outputs['Status'], 'identity_valid', identity_valid, 'BOOLEAN')
    # This scalar remains separate from the pavement provider's validity:
    # rejection of a separator must not suppress its valid surrounding patch.
    status = c._store(g, status, 'valid', valid, 'BOOLEAN')
    for name, value in (('st_cn_kind', SURFACE_KIND), ('st_cn_owner', region),
                        ('st_cn_region_id', region), ('st_ir_patch', patch)):
        status = c._store(g, status, name, value, 'INT')
    g.bind(c.choose(g, valid, result, original, 'GEOMETRY'), out.inputs['Geometry'])
    g.bind(status, out.inputs['Status']); g.bind(valid, out.inputs['Valid'])
    return g.g
